contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(uint amount) public payable {
        // require the test contract has enough balance to receive potential refunds (not strictly needed,
        // but keeps amounts bounded for the prover)
        require(amount <= type(uint).max);

        uint beforeBalance = address(c).balance;
        uint beforeDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdraw(amount); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            reverted = true;
        } else {
            reverted = false;
        }

        uint afterBalance = address(c).balance;
        uint afterDeposits = c.depositsCount(); if (__ESBMC_reverted()) return;

        uint expectedDecrease = beforeBalance >= amount ? amount : beforeBalance;

        // Single assert: if the call succeeded, depositsCount unchanged and balance decreased by expectedDecrease
        assert(reverted || (afterDeposits == beforeDeposits && beforeBalance - afterBalance == expectedDecrease));
    }

    receive() external payable {}
}

