pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 amount) internal {
        vm.assume(amount <= type(uint).max);
        uint beforeBalance = address(c).balance;
        uint256 beforeDeposits;
        try c.depositsCount() returns (uint256 __r) { beforeDeposits = __r; } catch { return; }
        bool reverted;
        try c.withdraw(amount) {
            reverted = false;
        } catch {
            reverted = true;
        }
        uint afterBalance = address(c).balance;
        uint256 afterDeposits;
        try c.depositsCount() returns (uint256 __r) { afterDeposits = __r; } catch { return; }
        uint expectedDecrease = beforeBalance >= amount ? amount : beforeBalance;
        assertTrue(reverted || (afterDeposits == beforeDeposits && beforeBalance - afterBalance == expectedDecrease));
    }

    function testFuzz_run(uint256 amount) public {
        _run(amount);
    }

    receive() external payable {}
}
